```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg rst;
    wire out;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .out(out)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus
        clk = 0;
        rst = 0;
        #10;
        rst = 1;
        #10;
        rst = 0;
        #10;
        clk = 1;
        #10;
        clk = 0;
        #10;
        clk = 1;
        #10;
        clk = 0;
        #10;

        // Verify outputs
        if (out !== 1'b0) begin
            errors = errors + 1;
        end
    end

    // Clock and reset generation
    initial begin
        #10;
        forever begin
            clk = ~clk;
            #10;
        end
    end

    initial begin
        #10;
        forever begin
            rst = 1;
            #10;
            rst = 0;
            #10;
        end
    end

    // Print test result
    final begin
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

